insert into public.exercises
  (company_id, name_en, name_es, cues_en, cues_es, muscle_group, equipment, difficulty, category, is_core, secondary_muscles)
values
  (null, 'Dumbbell Hip Thrust', 'Empuje de cadera con mancuerna', 'Sit with your upper back against the bench and the dumbbell across your hip crease, with a pad or folded towel under it. Set your feet so your shins are straight up and down at the top. Drive your hips up until your body is level, squeeze hard for a count, then lower slow. Ribs down and chin tucked the whole time, and breathe out as you drive up. If you feel this in your low back instead of your glutes, you''re arching to get height; stop at level and let your glutes finish the rep.', 'Siéntate con la espalda alta apoyada en la banca y la mancuerna cruzada sobre el pliegue de la cadera, con una toalla doblada debajo. Acomoda los pies para que arriba tus espinillas queden verticales. Sube la cadera hasta quedar en línea, aprieta fuerte un segundo y baja despacio. Costillas abajo, barbilla metida y saca el aire al subir. Si lo sientes en la espalda baja y no en los glúteos, estás arqueando para ganar altura; párate en la línea y deja que los glúteos terminen la repetición.', 'glutes', 'dumbbell', 'intermediate', 'strength', true, '{}'),
  (null, 'Single-Leg Hip Thrust', 'Empuje de cadera a una pierna', 'Same setup, upper back on the bench, then pick one foot to drive through. Push up on both feet first, then lift the other leg and start your reps from the top. Head, neck and chest move as one piece, and at the top think push tall. Hold the lifted leg in the exact same spot every rep instead of letting it drift down. If one hip drops or spins toward the lifted side, keep both hip bones level and pointed at the ceiling, and if it still tips, move to the staggered version instead of grinding it out.', 'Mismo montaje, espalda alta en la banca, y eliges un pie para empujar. Sube primero con los dos pies, luego levanta la otra pierna y empieza tus repeticiones desde arriba. Cabeza, cuello y pecho se mueven como una sola pieza, y arriba piensa en empujar alto. Mantén la pierna levantada en el mismo lugar en cada repetición, sin dejar que se te vaya cayendo. Si una cadera se cae o gira hacia el lado de la pierna levantada, deja los dos huesos de la cadera parejos y apuntando al techo; y si aun así se te ladea, pásate al empuje escalonado en vez de forzarlo.', 'glutes', 'body only', 'intermediate', 'strength', true, '{}'),
  (null, 'B-Stance Hip Thrust', 'Empuje de cadera escalonado', 'Set up like the dumbbell hip thrust, then slide one foot forward until its heel lines up with the toes of your working foot. Keep both feet close together side to side so the weight stays centered. The back leg does about 70 percent of the work; the front foot is just a kickstand resting on its heel. Drive up level, squeeze, lower slow, and finish all your reps on one side before you switch. If the set feels easy or that front foot goes flat and starts pushing, you''ve turned it back into a two-leg thrust; keep the front toes light and drop the weight instead of the stance.', 'Móntate igual que en el empuje con mancuerna y desliza un pie hacia adelante hasta que su talón quede a la altura de los dedos del pie que trabaja. Deja los dos pies cerca uno del otro para que el peso quede centrado. La pierna de atrás hace como el 70 por ciento; el pie de adelante es solo un apoyo, con el peso en el talón. Sube hasta quedar en línea, aprieta, baja despacio y haz todas las repeticiones de un lado antes de cambiar. Si se te hace fácil o el pie de adelante se aplana y empieza a empujar, volviste al empuje con las dos piernas; deja los dedos de adelante ligeritos y baja el peso, no la posición.', 'glutes', 'dumbbell', 'intermediate', 'strength', true, '{}'),
  (null, 'Banded Hip Thrust', 'Empuje de cadera con banda', 'Run the band across your hip crease with both ends under your feet, and pull the slack out before the first rep so there''s already tension at the bottom. Upper back on the bench, shins straight up and down at the top. Drive up to level and hold the squeeze for a full count, because the band is hardest right there and that''s the whole point of it. If you''re using a small band above your knees instead, press your knees out into it the whole way up. Don''t bounce off the floor and stop short at the top, because that skips the only part doing the work; take the bounce out and finish every rep all the way up.', 'Pasa la banda por el pliegue de la cadera con las dos puntas debajo de tus pies, y quítale el juego antes de la primera repetición para que ya haya tensión abajo. Espalda alta en la banca y espinillas verticales arriba. Sube hasta quedar en línea y aguanta el apretón un segundo completo, porque ahí es donde la banda jala más y ahí está todo el chiste. Si en vez de eso usas una banda chica arriba de las rodillas, ábrelas contra ella durante toda la subida. No rebotes en el piso ni te quedes corta arriba, porque ahí es justo donde está el trabajo; quita el rebote y termina cada repetición hasta arriba.', 'glutes', 'bands', 'beginner', 'strength', true, '{}'),
  (null, 'Machine Hip Thrust', 'Empuje de cadera en máquina', 'Set the back pad so it lands right under your shoulder blades, and the hip pad or belt across your hip crease, not on your belly. Move the foot platform until your shins are straight up and down at the top. Brace, breathe out, and drive your hips up through your heels until you''re level, squeeze, then lower slow. Ribs stay down, and that matters more here than anywhere because this is the heaviest you''ll load your glutes. If you can''t reach a clean, level lockout without your low back taking over, the machine is set wrong, not you; adjust the pads and the platform until you can.', 'Ajusta el respaldo para que te quede justo debajo de los omóplatos, y el cojín o cinturón cruzado sobre el pliegue de la cadera, nunca sobre la panza. Mueve la plataforma de los pies hasta que arriba tus espinillas queden verticales. Aprieta el abdomen, saca el aire y empuja la cadera hacia arriba con los talones hasta quedar en línea, aprieta y baja despacio. Costillas abajo, y aquí importa más que en ningún otro ejercicio porque es donde más peso vas a cargar. Si no logras llegar arriba parejita sin que la espalda baja tome el mando, la máquina está mal ajustada, no tú; mueve los cojines y la plataforma hasta que sí puedas.', 'glutes', 'machine', 'intermediate', 'strength', true, '{}'),
  (null, 'Frog Pump', 'Puente de rana', 'Lie on your back with the soles of your feet together, heels pulled in close to your glutes and your knees falling out wide. Rest the dumbbell across your hip crease with a pad under it, low back pressed flat into the floor, chin tucked. Squeeze your glutes to lift your hips, hold the top for two seconds, breathe out as you lift, and live in high reps here, 20 to 30. If your knees or the front of your hips pinch, slide your heels a few inches further out until the position feels clean. When your knees start creeping back together the exercise is over; keep them pressing wide and end the set right there instead of grinding out more.', 'Acuéstate boca arriba con las plantas de los pies juntas, los talones cerquita de los glúteos y las rodillas abiertas hacia los lados. Apoya la mancuerna sobre el pliegue de la cadera con una toalla debajo, la espalda baja pegadita al piso y la barbilla metida. Aprieta los glúteos para subir la cadera, aguanta dos segundos arriba, saca el aire al subir y trabaja en repeticiones altas, de 20 a 30. Si te molestan las rodillas o el frente de la cadera, aleja los talones unos centímetros hasta que la posición se sienta limpia. Cuando las rodillas empiecen a cerrarse, el ejercicio ya se acabó; mantenlas abiertas y termina la serie ahí en vez de forzar más.', 'glutes', 'dumbbell', 'beginner', 'strength', true, '{}'),
  (null, 'Banded Glute Bridge', 'Puente de glúteos con banda', 'Lie on your back with your feet flat and hip width, heels close enough that your shins are almost straight up at the top. Put the small band just above your knees on your thigh, never on the kneecap itself. Press your knees gently out into the band, breathe out, and lift your hips until your shoulders, hips and knees make one straight line. Squeeze at the top, lower slow, and hold that gentle press out for every rep. Don''t push past that straight line chasing more height, because those last inches come from your low back; stop at the line and let your glutes finish it.', 'Acuéstate boca arriba con los pies planos al ancho de la cadera y los talones cerca, para que arriba tus espinillas queden casi verticales. Coloca la banda chica justo arriba de las rodillas, sobre el muslo, nunca sobre la rótula. Abre las rodillas suavecito contra la banda, saca el aire y sube la cadera hasta que hombros, cadera y rodillas formen una línea recta. Aprieta arriba, baja despacio y mantén esa presión hacia afuera en cada repetición. No busques más altura pasando esa línea, porque esos centímetros de más salen de la espalda baja; párate en la línea y deja que los glúteos terminen el trabajo.', 'glutes', 'bands', 'beginner', 'strength', true, '{}'),
  (null, '45-Degree Back Extension', 'Extensión de espalda a 45 grados', 'Set the pad so its top edge sits two or three inches below your hip crease, so your hips can fold over it freely. Toes turned out, arms crossed on your chest, back flat: this is a hip hinge, not a back exercise. Lower slow until you feel a real stretch in your glutes and hamstrings, then squeeze them to bring you back up and stop at a straight line, no arching past it. Your bodyweight is plenty here, and if your low back has history, keep it that way and come up slow at the end of a set. If your hips can''t fold over that pad, you''ll be cranking from your low back every single rep; drop the pad until it sits just under your hip crease.', 'Ajusta el cojín para que su borde de arriba quede unos cinco centímetros debajo del pliegue de tu cadera, para que la cadera pueda doblarse libre. Puntas de los pies hacia afuera, brazos cruzados en el pecho y espalda plana: esto es una bisagra de cadera, no un ejercicio de espalda. Baja despacio hasta sentir un buen estiramiento en glúteos e isquiotibiales, aprieta para subir y párate en línea recta, sin arquear de más. Con tu propio peso basta, y si tu espalda baja ya te ha dado guerra, déjalo así y levántate despacio al terminar la serie. Si tu cadera no alcanza a doblarse sobre el cojín, vas a jalar con la espalda baja en cada repetición; baja el cojín hasta que quede justo debajo del pliegue de la cadera.', 'glutes', 'body only', 'intermediate', 'strength', true, '{}'),
  (null, 'Banded Pull-Through', 'Jalón entre piernas con banda', 'Anchor the band low and solid behind you, step over it so it runs between your legs, and walk forward until it''s pulling on you standing tall. Feet a little wider than your hips, knees soft, arms hanging long between your legs like ropes. Push your hips straight back and let the band pull your hands with them, chest folding forward with a flat back until you feel your hamstrings stretch. Squeeze your glutes to stand tall and stop there, ribs down, no leaning back at the top. Your hips go back, not down; if your knees travel forward as you lower, you''re squatting it, so set your knees once and let your hips do all the moving.', 'Ancla la banda bajita y firme detrás de ti, pásate por encima para que quede entre tus piernas y camina hacia adelante hasta que jale estando parada. Pies un poco más abiertos que la cadera, rodillas suaves y brazos colgando largos entre las piernas, como cuerdas. Manda la cadera hacia atrás y deja que la banda te jale las manos, el pecho baja con la espalda plana hasta que sientas el estiramiento en los isquiotibiales. Aprieta los glúteos para pararte derecha y ahí te detienes, costillas abajo, sin echarte para atrás. La cadera va hacia atrás, no hacia abajo; si tus rodillas se van hacia adelante al bajar, estás haciendo sentadilla, así que acomoda las rodillas una vez y deja que la cadera haga todo el movimiento.', 'glutes', 'bands', 'beginner', 'strength', true, '{}'),
  (null, 'Banded Donkey Kick', 'Patada de burro con banda', 'Get on all fours on a mat, hands under your shoulders, knees under your hips. Loop the band under both hands and over the arch of your working foot, keep that knee bent at 90 and your foot flexed. Ribs down, belly tight, and press your heel up toward the ceiling by squeezing the glute. Hold that squeeze for a second, then lower slow. If you have to arch your low back to get the leg higher, you have gone past your range, so stop where your thigh lines up with your back and squeeze harder instead of kicking higher.', 'Ponte en cuatro apoyos sobre un tapete, manos debajo de los hombros y rodillas debajo de la cadera. Pasa la banda por debajo de tus dos manos y por la planta del pie que trabaja, con esa rodilla doblada a 90 grados y el pie flexionado. Costillas abajo, abdomen firme, y empuja el talón hacia el techo apretando el glúteo. Aguanta ese apretón un segundo y baja despacio. Si tienes que arquear la espalda baja para subir más la pierna, ya te pasaste de tu rango: quédate donde el muslo llega a la línea de tu espalda y aprieta más fuerte en vez de patear más alto.', 'glutes', 'bands', 'beginner', 'strength', true, '{}'),
  (null, 'Banded Fire Hydrant', 'Hidrante con banda', 'On all fours, hands under your shoulders, knees under your hips, band just above your knees. Keep the working knee bent at 90, lift it out to the side, and point your toes out to the side too, not straight back. Go only as high as you can keep both hip bones pointed at the floor, then lower slow. You will feel the side of your glute, and the leg you are kneeling on will work too, that is normal. Most women lean away and roll the whole body over to get the knee higher, so keep even weight in both hands and stop the knee the second your hips start to turn.', 'En cuatro apoyos, manos debajo de los hombros, rodillas debajo de la cadera y la banda justo arriba de las rodillas. Mantén esa rodilla doblada a 90 grados, súbela hacia el lado y apunta la punta del pie hacia afuera, no hacia atrás. Sube solo hasta donde puedas mantener los dos huesos de la cadera mirando al piso, y baja despacio. Vas a sentir el costado del glúteo, y la pierna que está apoyada también trabaja, eso es normal. Casi todas se inclinan hacia el otro lado y giran el cuerpo para subir más la rodilla, así que reparte el peso parejo en las dos manos y detén la rodilla apenas la cadera empiece a girar.', 'abductors', 'bands', 'beginner', 'strength', true, '{glutes}'),
  (null, 'Banded Standing Kickback', 'Patada de glúteo de pie con banda', 'Stand tall with the band around both ankles and one hand on a wall or a chair. Soft knee on your standing leg, ribs down, hips level and facing forward. Press the working heel straight back like you are pushing into a wall behind you, squeeze, then come back slow instead of letting the band snap your leg forward. The range is small and that is correct, and your standing leg will burn too, that is normal. What goes wrong is the hip turning open to get the leg further back, so keep both hip bones facing front and your kneecap pointing down, and stop the moment you feel yourself twisting.', 'Párate derecha, con la banda en los dos tobillos y una mano apoyada en la pared o en una silla. Rodilla suave en la pierna de apoyo, costillas abajo, cadera pareja y de frente. Empuja el talón que trabaja hacia atrás, como si empujaras una pared detrás de ti, aprieta el glúteo y regresa despacio en vez de dejar que la banda te jale la pierna. El recorrido es corto y así debe ser, y la pierna de apoyo también te va a arder, eso es normal. Lo que falla aquí es que la cadera se abre para llevar la pierna más atrás, así que mantén los dos huesos de la cadera de frente, la rodilla apuntando al piso, y detente apenas sientas que te giras.', 'glutes', 'bands', 'intermediate', 'strength', true, '{}'),
  (null, 'Banded Side-Lying Clam', 'Almeja de lado con banda', 'Lie on your side, hips and shoulders stacked, knees bent, band just above your knees. Your heels stay glued together the whole set. Open your top knee toward the ceiling, pause, then close it slow instead of letting the band snap it shut. You should feel this high on the outside of your top glute, not in the front of your hip. Most women roll that top hip backward to open wider, so put your back against a wall and keep the range honest.', 'Acuéstate de lado, cadera y hombros alineados, rodillas dobladas y la banda justo arriba de las rodillas. Los talones se quedan pegados todo el set. Abre la rodilla de arriba hacia el techo, aguanta un segundo y ciérrala despacio, sin dejar que la banda te la cierre de golpe. Lo vas a sentir bien arriba, por fuera del glúteo de arriba, no al frente de la cadera. Casi todas giran esa cadera hacia atrás para abrir más, así que pega la espalda a la pared y quédate con el rango honesto.', 'abductors', 'bands', 'beginner', 'strength', true, '{glutes}'),
  (null, 'Side-Lying Hip Abduction', 'Abducción de cadera acostada de lado', 'Lie on your side in a straight line from ear to heel, bottom knee bent for a stable base. Lift the top leg toward the ceiling only as high as you can keep your hips stacked, then lower it slow without resting it down. Turn your toes down a little and lead with your heel; toes to the ceiling sends the work to the outside of your thigh. The burn belongs on the upper outside of your glute. If that leg starts drifting in front of you, put your back on a wall and graze your heel up it on every rep.', 'Acuéstate de lado, el cuerpo en línea recta de la oreja al talón, con la rodilla de abajo doblada para tener base. Sube la pierna de arriba hacia el techo solo hasta donde puedas mantener la cadera quieta, y bájala despacio sin descansarla. Gira los dedos del pie apenas hacia abajo y sube guiando con el talón; con los dedos apuntando al techo el trabajo se te va al costado del muslo. Lo tienes que sentir arriba, por fuera del glúteo. Si la pierna se te va hacia adelante, pega la espalda a la pared y roza el talón en ella en cada repetición.', 'abductors', 'body only', 'beginner', 'strength', true, '{glutes}'),
  (null, 'Banded Lateral Walk', 'Caminata lateral con banda', 'Loop the band around your ankles, or above your knees if your knees cave in. Sit into a quarter squat with your chest up and a small lean forward, and stay at that height the whole set. Step out wide with the lead leg, then bring the back foot in slow and place it, don''t let the band drag it. Both hips work here, and the standing leg should burn as much as the stepping one. If your feet end up touching between steps the band goes slack and the set empties out, so never let them get closer than hip width.', 'Pon la banda en los tobillos, o arriba de las rodillas si se te meten hacia adentro. Baja a una sentadilla de un cuarto, pecho arriba, con una inclinación chiquita hacia adelante, y quédate a esa altura todo el set. Da el paso ancho con la pierna de adelante y luego trae el pie de atrás despacio, apoyándolo, sin dejar que la banda te lo arrastre. Aquí trabajan las dos caderas, y la pierna de apoyo arde igual o más que la que da el paso. Si los pies se te juntan entre paso y paso la banda pierde tensión y el ejercicio se vacía, así que nunca los dejes más cerca del ancho de tu cadera.', 'abductors', 'bands', 'beginner', 'strength', true, '{glutes}'),
  (null, 'Seated Banded Hip Abduction', 'Abducción de cadera sentada con banda', 'Sit on the edge of a bench, feet flat and hip width, band above your knees on the muscle and never on the kneecap. Hold the bench and lean back a little; that angle stays the same for the whole set. Push your knees apart until the band is really pulling and hold a second at the widest point. Then take three slow seconds to come back in, and stop before your knees touch. Letting the band snap your knees shut is where most of the work gets lost, so make the way in the slow half.', 'Siéntate en la orilla de una banca, pies planos al ancho de la cadera, con la banda arriba de las rodillas, sobre el músculo y nunca sobre la rótula. Agárrate de la banca y échate un poco hacia atrás; ese ángulo no cambia en todo el set. Abre las rodillas hasta que la banda jale de verdad y aguanta un segundo bien abierta. Regresa contando tres segundos y frena antes de que las rodillas se toquen. Dejar que la banda te cierre las rodillas de golpe es donde se pierde casi todo el trabajo, así que la vuelta es la parte lenta.', 'abductors', 'bands', 'beginner', 'strength', true, '{glutes}'),
  (null, 'Standing Cable Hip Abduction', 'Abducción de cadera de pie en polea', 'Strap the cable to the ankle farthest from the machine and stand tall, side on, with a light hand on the frame for balance. Soft bend in the standing knee, hips square, shoulders level. Lift the working leg out to the side, not high, and bring it back slow against the cable instead of letting it pull you in. Both hips should be working: the standing glute is holding your pelvis level and it does more than you think. If your shoulders start tipping toward the machine you''re lifting with your waist, so drop the weight and cut the height in half.', 'Ponte la correa en el tobillo de la pierna más lejana a la máquina, párate de lado y bien derecha, con una mano apoyada en el marco solo para el equilibrio. La rodilla de apoyo suave, la cadera cuadrada, los hombros parejos. Sube la pierna hacia el costado, sin exagerar la altura, y regrésala despacio peleando con el cable en vez de dejar que te jale. Las dos caderas trabajan: el glúteo de la pierna de apoyo es el que mantiene la pelvis nivelada y hace más de lo que crees. Si los hombros se te empiezan a inclinar hacia la máquina estás subiendo con la cintura, así que baja el peso y sube la pierna la mitad.', 'abductors', 'cable', 'intermediate', 'strength', true, '{glutes}'),
  (null, 'Side Plank with Hip Abduction', 'Plancha lateral con abducción de cadera', 'Elbow under your shoulder, feet stacked, and push your hips up so your body is one straight line. Hold that line two seconds and check it before anything moves. Lift your top leg a few inches with your chest still facing forward, then lower it back down to your bottom foot. If you''re shaky, do the same thing from your bottom knee until the plank feels solid. The bottom hip drops the second the leg comes up, so think about pressing that hip a touch higher as the leg rises.', 'Codo debajo del hombro, pies encimados, y sube la cadera hasta que tu cuerpo sea una sola línea. Aguanta esa línea dos segundos y revísala antes de mover nada. Sube la pierna de arriba unos centímetros con el pecho todavía viendo al frente, y bájala hasta tocar el pie de abajo. Si te tiemblan las piernas, hazlo apoyada en la rodilla de abajo hasta que la plancha se sienta firme. La cadera de abajo se te cae en cuanto sube la pierna, así que piensa en empujarla un poquito más arriba mientras la pierna se levanta.', 'abductors', 'body only', 'intermediate', 'strength', true, '{glutes}'),
  (null, 'Dumbbell Romanian Deadlift', 'Peso muerto rumano con mancuernas', 'Hold the dumbbells against your thighs, feet hip width, and soften your knees just a little. Push your hips straight back like you''re closing a car door with your butt, and let the weights slide down your legs. Stop when you feel the stretch up the back of your thighs, usually around your knees, then squeeze your glutes to stand tall. Your back stays flat and your ribs stay down the whole way. If you''re reaching the weights toward the floor instead of pushing your hips back, shorten the range and think hips back, not weights down.', 'Sostén las mancuernas pegadas a los muslos, pies al ancho de cadera, y suaviza un poco las rodillas. Manda la cadera hacia atrás, como si cerraras la puerta del carro con los glúteos, y deja que las mancuernas se deslicen por tus piernas. Detente cuando sientas el estirón atrás del muslo, casi siempre a la altura de la rodilla, y aprieta los glúteos para subir. La espalda va recta y las costillas abajo todo el tiempo. Si estás bajando las mancuernas al piso en vez de mandar la cadera atrás, acorta el recorrido y piensa cadera atrás, no peso abajo.', 'hamstrings', 'dumbbell', 'beginner', 'strength', true, '{glutes}'),
  (null, 'Single-Leg Romanian Deadlift', 'Peso muerto rumano a una pierna', 'Dumbbell in the hand opposite your standing leg, and put a soft bend in that knee. Send your hips back and reach your free leg straight behind you, head and back heel moving together like one long line. Go until your body is about parallel to the floor, then drive your hip forward to stand. Go slow, and rest two fingers on a wall if you need to. Keep the toes of your back foot pointed straight down at the floor; the second that hip rolls open toward the ceiling you lose the hamstring, so square your hips back up and reset.', 'La mancuerna va en la mano contraria a la pierna que te sostiene, y esa rodilla queda apenas doblada. Manda la cadera hacia atrás y estira la otra pierna hacia atrás, cabeza y talón moviéndose como una sola línea. Baja hasta quedar más o menos paralela al piso y luego empuja la cadera al frente para subir. Hazlo lento, y apóyate con dos dedos en la pared si lo necesitas. Los dedos del pie de atrás apuntan al piso todo el tiempo; apenas esa cadera se abre hacia arriba pierdes el trabajo atrás del muslo, así que cuadra la cadera y empieza de nuevo.', 'hamstrings', 'dumbbell', 'intermediate', 'strength', true, '{glutes}'),
  (null, 'Bulgarian Split Squat', 'Sentadilla búlgara', 'Set your back foot on something about shin height, laces down, and step your front foot out about a step and a half. Stagger it a few inches to the side so you''re not on a tightrope. Drop your hips straight down, lean your chest forward a little over the front leg, and go until that thigh is about parallel. Drive up through the whole front foot, heel included, and let the back leg be a kickstand only. If your front knee is shooting way past your toes, your foot is too close to the bench; step it further out before the next rep.', 'Pon el pie de atrás en algo a la altura de la espinilla, con el empeine abajo, y el pie de adelante un paso y medio al frente. Sepáralo unos centímetros hacia el lado para que no quedes en la cuerda floja. Baja la cadera derechito, inclina un poco el pecho sobre la pierna de adelante y llega hasta que ese muslo quede casi paralelo. Sube empujando con todo el pie de adelante, talón incluido, y usa la pierna de atrás solo como apoyo. Si la rodilla de adelante se te va muy por delante de los dedos, el pie está muy cerca del banco; adelántalo más antes de la siguiente repetición.', 'glutes', 'dumbbell', 'intermediate', 'strength', true, '{}'),
  (null, 'Reverse Lunge', 'Zancada hacia atrás', 'Stand tall with the dumbbells at your sides and shift your weight onto your front foot before you move. Step the other foot back and lower until that back knee is an inch off the floor, heel stays up. Your front foot never moves the whole set, and about 90 percent of you stays on it. Lean your chest forward a touch to feel it more in the glute, then drive your front heel down to stand. If you''re pushing off the back foot to come up, keep that back toe light and pause a second at the bottom; the front leg is the one working.', 'Párate derecha con las mancuernas a los lados y pasa tu peso al pie de adelante antes de moverte. Da un paso atrás con el otro pie y baja hasta que esa rodilla quede a un dedo del piso, con el talón levantado. El pie de adelante no se mueve en toda la serie, y ahí se queda como el 90 por ciento de tu peso. Inclina el pecho un poquito al frente para sentirlo más en el glúteo y sube empujando el talón de adelante contra el piso. Si te estás impulsando con el pie de atrás, déjalo ligerito y haz una pausa de un segundo abajo; la pierna que trabaja es la de adelante.', 'glutes', 'dumbbell', 'beginner', 'strength', true, '{}'),
  (null, 'Curtsy Lunge', 'Zancada cruzada', 'Stand tall, then step one foot back and across behind the other, landing on the ball of that foot. Your standing foot stays planted and pointed forward, hips square, and you drop straight down. Keep it shallow and light here; the work is in controlling the direction, not in how deep you go. If your knees are cranky or this pinches, do reverse lunges instead and you lose nothing. Watch that standing knee: the second it caves toward the middle, push through the outside of your heel and point the knee at your second toe.', 'Párate derecha, luego lleva un pie hacia atrás y cruzado por detrás del otro, apoyando la punta. El pie que te sostiene se queda plantado y apuntando al frente, la cadera cuadrada, y bajas derechito. Aquí quédate poco profunda y con poco peso; el trabajo está en controlar la dirección, no en qué tan abajo llegas. Si tus rodillas están molestas o esto te pincha, haz zancadas hacia atrás y no pierdes nada. Cuida la rodilla que te sostiene: apenas se meta hacia adentro, empuja con la parte de afuera del talón y apúntala hacia tu segundo dedo.', 'glutes', 'dumbbell', 'intermediate', 'strength', true, '{}'),
  (null, 'Lateral Lunge', 'Zancada lateral', 'Feet start together with both toes pointed straight ahead, and they stay that way. Step wide to one side, land flat, and sit your hips back and down over that leg. The other leg stays long and straight with the heel down, and your chest comes over the working thigh with a flat back. Push through the working heel to come back to the middle. If you''re bending sideways at the waist instead of sitting your hips back, take a narrower step and lead with your hips, not your shoulder.', 'Empiezas con los pies juntos, los dos apuntando al frente, y así se quedan. Da un paso amplio hacia un lado, apoya todo el pie y sienta la cadera atrás y abajo sobre esa pierna. La otra pierna queda larga y estirada con el talón pegado al piso, y el pecho baja sobre el muslo que trabaja con la espalda recta. Regresa al centro empujando con el talón de la pierna que trabaja. Si te estás doblando de lado por la cintura en vez de mandar la cadera atrás, da un paso más corto y guía con la cadera, no con el hombro.', 'glutes', 'dumbbell', 'beginner', 'strength', true, '{}'),
  (null, 'Goblet Squat', 'Sentadilla con mancuerna al pecho', 'Hold one dumbbell straight up against your chest, hands cupping the top, elbows tucked in tight. Feet between hip and shoulder width with your toes turned out a little, wherever your hips feel open. Sit straight down between your hips with your knees pushing out over your toes, and go as low as you can while your back stays flat. Drive up through the middle of your foot, hips and chest rising together. If the dumbbell starts drifting off your chest, that''s your upper back giving out and not your legs; glue it back to your sternum and end the set there.', 'Sujeta una mancuerna en vertical pegada al pecho, las manos en la parte de arriba y los codos bien metidos. Los pies entre el ancho de cadera y el de hombros, con las puntas un poco hacia afuera, donde tu cadera se sienta cómoda. Baja derechito entre las caderas, con las rodillas abriéndose hacia las puntas de los pies, y llega tan abajo como puedas manteniendo la espalda recta. Sube empujando con el centro del pie, cadera y pecho subiendo al mismo tiempo. Si la mancuerna se te empieza a despegar del pecho, es la espalda alta la que se está cansando y no las piernas; pégala otra vez al esternón y ahí termina la serie.', 'quadriceps', 'dumbbell', 'beginner', 'strength', true, '{glutes}'),
  (null, 'Lateral Step-Up', 'Subida lateral al cajón', 'Stand beside a solid box with the working leg closest to it, and keep it low enough that your hips stay level at the top; six inches is plenty to start. Put that whole foot on the box, weight through the heel and midfoot, and press up sideways until the leg is straight and your hips are even. Let the other foot hover, it''s along for the ride. Come down slow, two or three counts, and just tap the floor before the next rep. If you''re bouncing off the bottom foot to get up, start each rep with that toe already lifted and pause at the bottom so the working leg has to do it.', 'Párate al lado de un cajón firme, con la pierna que trabaja del lado más cercano, y que quede bajito para que la cadera se mantenga pareja arriba; quince centímetros bastan para empezar. Sube todo ese pie al cajón, con el peso en el talón y el medio pie, y empuja hacia arriba de lado hasta estirar la pierna y quedar con la cadera pareja. El otro pie se queda flotando, va de pasajero. Baja lento, dos o tres tiempos, y solo toca el piso antes de la siguiente repetición. Si te estás impulsando con el pie de abajo, empieza cada repetición con esa punta ya levantada y haz una pausa abajo para que la pierna que trabaja haga el trabajo.', 'glutes', 'dumbbell', 'beginner', 'strength', true, '{}')
